use std::collections::BTreeMap;#[derive(Default,Clone,Copy)]struct S{n:bool,p:bool}#[derive(Default)]pub struct Actions{m:BTreeMap<String,Vec<u16>>,s:BTreeMap<String,S>}impl Actions{pub fn bind(&mut self,a:&str,k:u16){self.m.entry(a.into()).or_default().push(k)}pub fn update(&mut self,f:impl Fn(u16)->bool){for(a,k)in&self.m{let s=self.s.entry(a.clone()).or_default();s.p=s.n;s.n=k.iter().any(|x|f(*x))}}pub fn held(&self,a:&str)->bool{self.s.get(a).is_some_and(|x|x.n)}pub fn pressed(&self,a:&str)->bool{self.s.get(a).is_some_and(|x|x.n&&!x.p)}pub fn released(&self,a:&str)->bool{self.s.get(a).is_some_and(|x|!x.n&&x.p)}}
